{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "The closest analogue (Morgan 0.35), a tolyl-urea compound, has human oral bioavailability of 78.6%, supporting high F for the query's aryl-urea/sulfonylurea-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Tolbutamide, a sulfonylurea oral antidiabetic, has absolute oral bioavailability of 85% in humans, directly demonstrating that the sulfonylurea chemotype can achieve F well above 20% despite acidic ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pimasertib, which shares the pyridine-aniline core, has absolute oral bioavailability of 73% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lumiracoxib, an acidic and ionizable drug, has absolute oral bioavailability of 74%, showing that ionization and polarity alone do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lisofylline is a low-bioavailability outlier (5.9%), but its low Morgan similarity and different chemotype limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable physicochemical prior, multiple transferable experimental analogues—especially sulfonylurea tolbutamide and pyridine-aniline pimasertib—show high absolute oral bioavailability (64–85%), outweighing the single low-bioavailability outlier. Prediction: high (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All analogues have low Morgan similarity (<0.36).",
    "No data specific to the cirrhosis condition.",
    "Conflicting bupropion bioavailability records were not used as decisive evidence.",
    "Lisofylline low F is structurally distant and of limited transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

